import * as THREE from 'three';
import {{ STLLoader }} from 'three/addons/loaders/STLLoader.js';
import {{ OrbitControls }} from 'three/addons/controls/OrbitControls.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);

const camera = new THREE.PerspectiveCamera(45, innerWidth/innerHeight, 0.1, 100);
camera.position.set(14, 10, 18);
camera.lookAt(0, 2.5, 0);

const renderer = new THREE.WebGLRenderer({{ antialias: true }});
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
renderer.shadowMap.enabled = true;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 2.5, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.update();

const ambientLight = new THREE.AmbientLight(0x404060, 3);
scene.add(ambientLight);

const keyLight = new THREE.DirectionalLight(0xffffff, 6);
keyLight.position.set(10, 18, 10);
keyLight.castShadow = true;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888cc, 2);
fillLight.position.set(-8, 5, -5);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight(0xffffff, 3);
rimLight.position.set(0, 8, -10);
scene.add(rimLight);

const grid = new THREE.GridHelper(18, 18, 0x444466, 0x222244);
grid.position.y = -3.3;
scene.add(grid);

// Load STL from base64
const stlBin = Uint8Array.from(atob("{stl_b64}"), c => c.charCodeAt(0));
const blob = new Blob([stlBin], {{ type: 'application/octet-stream' }});
const url = URL.createObjectURL(blob);

const loader = new STLLoader();
loader.load(url, geometry => {{
  const mesh = new THREE.Mesh(
    geometry,
    new THREE.MeshStandardMaterial({{ color: 0x222222, roughness: 0.7, metalness: 0.05 }})
  );
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);

  // Fit camera
  geometry.computeBoundingBox();
  const box = geometry.boundingBox;
  const center = new THREE.Vector3();
  box.getCenter(center);
  const size = new THREE.Vector3();
  box.getSize(size);
  const maxDim = Math.max(size.x, size.y, size.z);
  camera.position.set(maxDim*1.5, maxDim*0.8, maxDim*1.8);
  controls.target.copy(new THREE.Vector3(0, center.y, 0));
  controls.update();

  URL.revokeObjectURL(url);
}});

function animate() {{
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}}
animate();

window.addEventListener('resize', () => {{
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
}});
</script>
</body>
</html>'''

